/** Index of NEVER by route key, for O(1) lookup in the guard and the sync test. */
export const neverByKey: ReadonlyMap<RouteKey, NeverEntry> = new Map(
  NEVER.map((entry) => [routeKey(entry.method, entry.path), entry] as const),
);

export function isNever(method: string, path: string): boolean {
  return neverByKey.has(routeKey(method, path));
}
